/**
 * The head of an about screen (B10a, spec/02 §3.24): the 64 dp sign tile of [product] with [glyph] (its
 * complete tile drawable, SbSignTile), hidden from TalkBack, then [name] in title (a heading), the one-liner [line] in body
 * and „Version 1.4.0 vom 20.10.2026“ (aboutVersion; [version] in sebaro Mono, [date] the caller's text) in caption
 * textMuted. The text keeps 192 dp times the text scale (the web's 12rem) beside the tile, else it moves under it;
 * never centred. 16 dp above and below, the gutter at the sides. SbFactsLine follows directly under it.
 * §14.17 (2026-10-26; provisional, agent): [product] or [glyph] null = an app without a sign yet, no tile and the text
 * from the start; [date] null = „Version 1.4.0“ alone (aboutVersionOnly).
 */
@Composable
fun SbAboutHead(
    product: SebaroProduct?,
    glyph: Painter?,
    name: String,
    line: String,
    version: String,
    date: String?,
    modifier: Modifier = Modifier,
) {
    val t = SebaroTheme.tokens
    val tile = t.space.s16
    if (product == null || glyph == null) {
        SbAboutText(
            name,
            line,
            version,
            date,
            modifier
                .fillMaxWidth()
                .padding(horizontal = t.spacing.gutter, vertical = t.space.s4),
        )
        return
    }
    BoxWithConstraints(
        modifier
            .fillMaxWidth()
            .padding(horizontal = t.spacing.gutter, vertical = t.space.s4),
    ) {
        // the web's flex: 1 1 12rem; the rem grows with the text (provisional, agent)
        val side = maxWidth - tile - t.space.s4 >= t.space.s16 * 3 * sbTextScale()
        if (side) {
            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(t.space.s4)) {
                SbSignTile(product, glyph, contentDescription = null, size = tile)
                SbAboutText(name, line, version, date, Modifier.weight(1f))
            }
        } else {
            Column(verticalArrangement = Arrangement.spacedBy(t.space.s3)) {
                SbSignTile(product, glyph, contentDescription = null, size = tile)
                SbAboutText(name, line, version, date, Modifier.fillMaxWidth())
            }
        }
    }
}

/** Name (title, a heading), one-liner (body) and the version line (caption textMuted, the version in mono), 2 dp apart. */
@Composable
private fun SbAboutText(name: String, line: String, version: String, date: String?, modifier: Modifier) {
    val c = SebaroTheme.colors
    val ty = SebaroTheme.typography
    val meta = if (date != null) sbMessages().aboutVersion(version, date) else sbMessages().aboutVersionOnly(version)
    val at = meta.indexOf(version)
    val text = buildAnnotatedString {
        append(meta)
        if (at >= 0) addStyle(SpanStyle(fontFamily = ty.code.fontFamily, fontWeight = ty.code.fontWeight), at, at + version.length)
    }
    Column(modifier, verticalArrangement = Arrangement.spacedBy(SebaroTheme.tokens.space.s0_5)) {
        Text(name, style = ty.title, color = c.text, modifier = Modifier.semantics { heading() })
        Text(line, style = ty.body, color = c.text)
        Text(text, style = ty.caption, color = c.textMuted)
    }
}
